s": "3L", "substrate": "285 nm SiO2/Si", "temperature_K": null, "spectral_resolution_cm1": 2.7}, "note": "", "rel_intensity": null, "source": {"citation": "Lee et al. 2010, ACS Nano 4, 2695", "doi": "10.1021/nn1003937", "arxiv": "1005.2509", "locator": "Fig. 2b"}, "provenance": "literature"}, {"position_cm1": 405.9, "label": "A1g", "irrep": "A1g", "conditions": {"laser_nm": 514.5, "layers": "3L", "substrate": "285 nm SiO2/Si", "temperature_K": null, "spectral_resolution_cm1": 2.7}, "note": "", "rel_intensity": null, "source": {"citation": "Lee et al. 2010, ACS Nano 4, 2695", "doi": "10.1021/nn1003937", "arxiv": "1005.2509", "locator": "Fig. 2b"}, "provenance": "literature"}, {"position_cm1": 382.4, "label": "E2g1", "irrep": "E2g", "conditions": {"laser_nm": 514.5, "layers": "4L", "substrate": "285 nm SiO2/Si", "temperature_K": null, "spectral_resolution_cm1": 2.7}, "note": "", "rel_intensity": null, "source": {"citation": "Lee et al. 2010, ACS Nano 4, 2695", "doi": "10.1021/nn1003937", "arxiv": "1005.2509", "locator": "Fig. 2b"}, "provenance": "literature"}, {"position_cm1": 406.7, "label": "A1g", "irrep": "A1g", "conditions": {"laser_nm": 514.5, "layers": "4L", "substrate": "285 nm SiO2/Si", "temperature_K": null, "spectral_resolution_cm1": 2.7}, "note": "", "rel_intensity": null, "source": {"citation": "Lee et al. 2010, ACS Nano 4, 2695", "doi": "10.1021/nn1003937", "arxiv": "1005.2509", "locator": "Fig. 2b"}, "provenance": "literature"}, {"position_cm1": 382.2, "label": "E2g1", "irrep": "E2g", "conditions": {"laser_nm": 514.5, "layers": "bulk", "substrate": "285 nm SiO2/Si", "temperature_K": null, "spectral_resolution_cm1": 2.7}, "note": "", "rel_intensity": null, "source": {"citation": "Lee et al. 2010, ACS Nano 4, 2695", "doi": "10.1021/nn1003937", "arxiv": "1005.2509", "locator": "Fig. 2b"}, "provenance": "literature"}, {"position_cm1": 407.4, "label": "A1g", "irrep": "A1g", "conditions": {"laser_nm": 514.5, "layers": "bulk", "substrate": "285 nm SiO2/Si", "temperature_K": null, "spectral_resolution_cm1": 2.7}, "note": "", "rel_intensity": null, "source": {"citation": "Lee et al. 2010, ACS Nano 4, 2695", "doi": "10.1021/nn1003937", "arxiv": "1005.2509", "locator": "Fig. 2b"}, "provenance": "literature"}], "conditional_modes": [], "notes": ["Defects: LA(M) at about 227 cm-1 is the most prominent defect-activated peak; I(LA)/I(first order) grows with defect density (Mignuzzi et al. 2015, Phys. Rev. B 91, 195411, abstract and text). Not a mode entry because its DOI or arXiv id was not verified.", "Lee et al. use bulk (D6h) labels for all layer numbers; in the monolayer (D3h) the same modes are E' and A1'.", "Linewidths (Lee et al. 2010, text p.4): Gamma(E2g1) about 2.1 cm-1; Gamma(A1g) 3 to 6 cm-1 from 6L to 2L."], "omitted": [], "provenance": "literature"}
