{"relations": [{"name": "mos2_layer_number_from_separation", "material": "MoS2", "aliases": ["2H-MoS2", "molybdenum disulfide"], "inputs": {"delta_E2g_A1g_cm1": "omega(A1g) - omega(E2g1) in cm-1, from a Lorentzian fit of both modes"}, "optional_inputs": {"laser_nm": "excitation wavelength in nm", "delta_err_cm1": "1-sigma uncertainty of the separation in cm-1 (default 0.5)"}, "outputs": {"layer_label": "1L, 2L, 3L, 4L or bulk", "layer_number": "int, None for bulk", "candidates": "layer labels within the uncertainty of the measured separation", "confidence": "high (one candidate, 1L or 2L), moderate (one candidate), low (several)"}, "equation": "Delta = omega(A1g) - omega(E2g1). Tabulated (Lee 2010, Fig. 2b, 514.5 nm): 1L 19.1, 2L 21.4, 3L 23.1, 4L 24.3, bulk 25.2 cm-1. layer = argmin_N |Delta - Delta_N|; candidates = all N with |Delta - Delta_N| <= delta_err.", "validity": {"delta_range_cm1": [18.1, 26.2], "laser_nm": [488.0, 633.0], "substrate": "SiO2/Si (285 nm oxide in the source)", "sample": "mechanically exfoliated 2H-MoS2"}, "source": {"citation": "Lee, Yan, Brus, Heinz, Hone, Ryu 2010, ACS Nano 4, 2695", "locator": "Fig. 2b (E2g1 and A1g positions and their difference vs layer number, 514.5 nm)", "doi": "10.1021/nn1003937", "arxiv": "1005.2509"}, "caveats": ["Table measured at 514.5 nm with 2.7 cm-1 spectral resolution on 285 nm SiO2/Si (Lee 2010); 3L, 4L and bulk differ by about 1 cm-1, so they are separable only with a well-calibrated fit.", "Strain, doping and substrate shift E2g1 and A1g and therefore Delta; a CVD or transferred flake can be misassigned by one layer."], "self_tests": [{"inputs": {"delta_E2g_A1g_cm1": 19.1}, "expected": {"layer_label": "1L", "layer_number": 1}, "tolerance": {}, "locator": "Fig. 2b, 1L"}, {"inputs": {"delta_E2g_A1g_cm1": 21.4}, "expected": {"layer_label": "2L", "layer_number": 2}, "tolerance": {}, "locator": "Fig. 2b, 2L"}, {"inputs": {"delta_E2g_A1g_cm1": 23.1}, "expected": {"layer_label": "3L", "layer_number": 3}, "tolerance": {}, "locator": "Fig. 2b, 3L"}, {"inputs": {"delta_E2g_A1g_cm1": 24.3}, "expected": {"layer_label": "4L", "layer_number": 4}, "tolerance": {}, "locator": "Fig. 2b, 4L"}, {"inputs": {"delta_E2g_A1g_cm1": 25.2}, "expected": {"layer_label": "bulk", "layer_number": null}, "tolerance": {}, "locator": "Fig. 2b, bulk"}]}, {"name": "ws2_layer_number_from_separation", "material": "WS2", "aliases": ["2H-WS2", "tungsten disulfide"], "inputs": {"delta_E2g_A1g_cm1": "omega(A1g) - omega(E2g1) in cm-1, from a Lorentzian fit of both modes"}, "optional_inputs": {"laser_nm": "excitation wavelength in nm", "delta_err_cm1": "1-sigma uncertainty of the separation in cm-1 (default 0.5)"}, "outputs": {"layer_label": "1L, 2L, 3L, 4L or bulk", "layer_number": "int, None for bulk", "candidates": "layer labels within the uncertainty of the measured separation", "confidence": "high (one candidate, 1L or 2L), moderate (one candidate), low (several)"}, "equation": "Delta = omega(A1g) - omega(E2g1). Tabulated (Berkdemir 2013, Table 1, 514.5 nm): 1L 62.0, 2L 63.4, 3L 64.6, bulk 64.8 cm-1. layer = argmin_N |Delta - Delta_N|; candidates = all N with |Delta - Delta_N| <= delta_err.", "validity": {"delta_range_cm1": [61.0, 66.0], "laser_nm": [488.0, 647.0], "substrate": "SiO2/Si (CVD layers in the source; bulk on powder)"}, "source": {"citation": "Berkdemir et al. 2013, Sci. Rep. 3, 1755", "locator": "Table 1 (2LA(M), E2g1, A1g positions per layer number at 488, 514.5, 647 nm)", "doi": "10.1038/srep01755", "arxiv": null}, "caveats": ["3L (64.6) and bulk (64.8 cm-1) are not separable by this relation (Berkdemir 2013, Table 1).", "At 514.5 nm the 2LA(M) band at about 351 cm-1 sits 4 cm-1 below E2g1 (Berkdemir 2013, Table 1); a single-Lorentzian fit of the pair pulls E2g1 low and Delta high. Fit both components."], "self_tests": [{"inputs": {"delta_E2g_A1g_cm1": 62.0, "laser_nm": 514.5}, "expected": {"layer_label": "1L", "layer_number": 1}, "tolerance": {}, "locator": "Table 1, 514.5 nm, 1L: A1g 417.2, E2g1 355.2"}, {"inputs": {"delta_E2g_A1g_cm1": 63.4, "laser_nm": 514.5}, "expected": {"layer_label": "2L", "layer_number": 2}, "tolerance": {}, "locator": "Table 1, 514.5 nm, 2L: A1g 418.4, E2g1 355.0"}, {"inputs": {"delta_E2g_A1g_cm1": 61.6, "laser_nm": 488.0}, "expected": {"layer_label": "1L", "layer_number": 1}, "tolerance": {}, "locator": "Table 1, 488 nm, 1L: A1g 417.5, E2g1 355.9"}]}, {"name": "graphene_defect_distance_from_ID_IG", "material": "graphene", "aliases": ["monolayer graphene", "single-layer graphene"], "inputs": {"I_D_over_I_G": "ratio of the D and G peak HEIGHTS (not areas)", "laser_nm": "excitation wavelength in nm"}, "optional_inputs": {}, "outputs": {"L_D_nm": "mean distance between point defects in nm (Eq. 4)", "L_D_err_nm": "uncertainty from the +-0.5 on the 1.8e-9 constant", "n_D_cm2": "point-defect density in cm-2 (Eq. 6)", "L_D_nm_energy_form": "the same from Eq. 3 (laser energy form), as a cross-check"}, "equation": "L_D^2 [nm^2] = (1.8 +- 0.5) x 1e-9 lambda_L^4 (I_D/I_G)^-1 (Eq. 4), lambda_L laser wavelength in nm; n_D [cm-2] = (1.8 +- 0.5) x 1e22 / lambda_L^4 (I_D/I_G) (Eq. 6); equivalently L_D^2 = (4.3 +- 1.3) x 1e3 / E_L^4 (I_D/I_G)^-1 with E_L in eV (Eq. 3). I_D, I_G are peak heights.", "validity": {"L_D_nm": ">= 10 (low-defect regime, stage 1)", "laser": "visible excitation (paper: 514.5, 632.8, 785 nm)", "laser_nm": [400.0, 786.0], "sample": "single-layer graphene, point defects"}, "source": {"citation": "Cancado et al. 2011, Nano Lett. 11, 3190", "locator": "Eqs. (3) to (6), p. 4 of arXiv 1105.0175v2; validity statement p. 4", "doi": "10.1021/nl201432g", "arxiv": "1105.0175"}, "caveats": ["I_D/I_G rises with defect density until L_D is about 3 nm and falls below it (Cancado 2011, abstract), so one ratio maps to two L_D values; this relation assumes the low-defect branch. A broad G band or a D band comparable in width to G points to the high-defect branch.", "Equations hold for point defects; edges and grain boundaries also give a D band."], "self_tests": [{"inputs": {"I_D_over_I_G": 0.5, "laser_nm": 514.5}, "expected": {"L_D_nm": 15.967, "n_D_cm2": 123100000000.0}, "tolerance": {"L_D_nm": 0.3, "n_D_cm2": 8000000000.0}, "locator": "Eq. 3 and Eq. 5 at E_L = 2.41 eV"}, {"inputs": {"I_D_over_I_G": 1.0, "laser_nm": 632.8}, "expected": {"L_D_nm": 17.07, "n_D_cm2": 107700000000.0}, "tolerance": {"L_D_nm": 0.3, "n_D_cm2": 8000000000.0}, "locator": "Eq. 3 and Eq. 5 at E_L = 1.96 eV"}, {"inputs": {"I_D_over_I_G": 2.0, "laser_nm": 785.0}, "expected": {"L_D_nm": 18.574, "n_D_cm2": 91000000000.0}, "tolerance": {"L_D_nm": 0.3, "n_D_cm2": 8000000000.0}, "locator": "Eq. 3 and Eq. 5 at E_L = 1.58 eV"}]}, {"name": "graphene_strain_doping_from_G_2D", "material": "graphene", "aliases": ["monolayer graphene", "single-layer graphene"], "inputs": {"omega_G_cm1": "G peak position in cm-1", "omega_2D_cm1": "2D peak position in cm-1"}, "optional_inputs": {"laser_nm": "excitation wavelength in nm (must be 514 nm)", "strain_type": "'uniaxial' (default) or 'biaxial'; sets the G shift per % strain"}, "outputs": {"delta_omega_G_strain_cm1": "G shift along the strain direction e_T", "delta_omega_G_doping_cm1": "G shift along the hole-doping direction e_H", "strain_percent": "strain in %, tensile positive", "doping_type": "'hole' or 'undetermined (low density)'", "a_cm1": "length along e_T", "b_cm1": "length along e_H"}, "equation": "OP = (omega_G - 1581.6, omega_2D - 2676.9) = a e_T + b e_H, with unit vectors e_T along slope d(omega_2D)/d(omega_G) = 2.2 (strain) and e_H along slope 0.70 (hole doping). Strain from the G part of a e_T: epsilon [%] = delta_omega_G_strain / (-23.5) uniaxial or / (-69.1) biaxial.", "validity": {"laser_nm": [513.0, 516.0], "sample": "single-layer graphene", "doping": "holes only (the paper excludes electron doping)", "omega_G_cm1": [1560.0, 1610.0], "omega_2D_cm1": [2620.0, 2720.0]}, "source": {"citation": "Lee, Ahn, Shim, Lee, Ryu 2012, Nat. Commun. 3, 1024", "locator": "origin (1581.6, 2676.9) p. 4; unit vectors e_T (slope 2.2) and e_H (slope 0.70) p. 5; G strain sensitivities in the Fig. 3 legend; 514 nm limit p. 9 of arXiv 1209.0234", "doi": null, "arxiv": "1209.0234"}, "caveats": ["Carrier density is not converted to cm-2: the source maps G shift to n along a nonlinear measured trajectory, not a linear rate (Lee 2012, Fig. 3 legend).", "Near the origin (|n| about 1e12 cm-2) the decomposition is ambiguous; errors up to 0.03 % strain and 1.5e12 cm-2 (Lee 2012, pp. 5 to 6).", "Strain sensitivities -23.5 (uniaxial) and -69.1 +- 3.4 cm-1/% (biaxial) are quoted by Lee 2012 from other references (Fig. 3 legend); the strain type must be known."], "self_tests": [{"inputs": {"omega_G_cm1": 1581.6, "omega_2D_cm1": 2676.9, "laser_nm": 514.5}, "expected": {"strain_percent": 0.0, "delta_omega_G_doping_cm1": 0.0}, "tolerance": {"strain_percent": 1e-09, "delta_omega_G_doping_cm1": 1e-09}, "locator": "p. 4: freestanding graphene F1, strain-free and nearly undoped, is the origin"}, {"inputs": {"omega_G_cm1": 1591.5, "omega_2D_cm1": 2693.0, "laser_nm": 514.5}, "expected": {"doping_type": "hole"}, "tolerance": {}, "locator": "p. 7: sample K4 after 400 C, (1591.5, 2693), 'strong hole doping'"}, {"inputs": {"omega_G_cm1": 1598.4, "omega_2D_cm1": 2698.0, "laser_nm": 514.5}, "expected": {"doping_type": "hole"}, "tolerance": {}, "locator": "p. 7: sample K4 after 500 C, (1598.4, 2698), 'strong hole doping'"}]}, {"name": "graphene_layers_from_2D_shape", "material": "graphene", "aliases": ["monolayer graphene", "single-layer graphene"], "inputs": {"n_2D_components": "number of Lorentzian components needed to fit the 2D band (1, 2 or 4)"}, "optional_inputs": {"I_2D_over_I_G": "ratio of the 2D and G peak heights", "laser_nm": "excitation wavelength in nm"}, "outputs": {"layer_class": "'monolayer', 'bilayer' or 'bulk graphite (or more than 5 layers)'", "confidence": "high, moderate or low"}, "equation": "Line-shape lookup (Ferrari 2006, p. 2): one sharp 2D component about 4 times the G height -> monolayer; four components (2D1B, 2D1A, 2D2A, 2D2B) -> bilayer; two components 2D1, 2D2 at about 1/4 and 1/2 of the G height -> bulk graphite.", "validity": {"n_2D_components": [1, 2, 4], "laser_nm": [510.0, 640.0], "sample": "Bernal-stacked graphene; turbostratic graphite also shows a single (twice as wide) 2D peak"}, "source": {"citation": "Ferrari et al. 2006, Phys. Rev. Lett. 97, 187401", "locator": "p. 2 (single sharp 2D peak in graphene, 4 components in bilayer, 2 in bulk graphite) and Fig. 2 of arXiv cond-mat/0606284", "doi": null, "arxiv": "cond-mat/0606284"}, "caveats": ["Spectra of more than 5 layers are hardly distinguishable from bulk graphite (Ferrari 2006, p. 2); 3 to 5 layers are not classified by this relation.", "Turbostratic graphite has a single 2D peak with FWHM about 50 cm-1, almost double that of graphene (Ferrari 2006, p. 3); check the width when one component is found."], "self_tests": [{"inputs": {"n_2D_components": 1, "I_2D_over_I_G": 4.0}, "expected": {"layer_class": "monolayer", "confidence": "high"}, "tolerance": {}, "locator": "p. 2: 'a single, sharp 2D peak in graphene, roughly 4 times more intense than the G peak'"}, {"inputs": {"n_2D_components": 4}, "expected": {"layer_class": "bilayer"}, "tolerance": {}, "locator": "p. 2 and Fig. 2e: bilayer 2D has 4 components"}, {"inputs": {"n_2D_components": 2}, "expected": {"layer_class": "bulk graphite (or more than 5 layers)"}, "tolerance": {}, "locator": "p. 2: 'The 2D peak in bulk graphite consists of two components 2D1 and 2D2'"}]}, {"name": "crsbr_ag_mode_assignment_with_polarization_axis", "material": "CrSBr", "aliases": ["chromium sulfide bromide"], "inputs": {"position_cm1": "fitted peak position in cm-1"}, "optional_inputs": {"laser_eV": "excitation photon energy in eV", "laser_nm": "excitation wavelength in nm", "max_parallel_angle_deg": "lab-frame angle of maximum parallel-polarized intensity", "measured_max_axis": "'a' or 'b' if the crystal axes are known independently"}, "outputs": {"mode_label": "Ag1, Ag2 or Ag3", "irrep": "Ag", "expected_max_axis": "'a', 'b', 'near isotropic (switching)' or None (not measured at this energy)", "b_axis_angle_deg": "lab-frame angle of the b axis, from max_parallel_angle_deg (Ag1, Ag3, or Ag2 when its axis is known)", "consistent": "measured axis equals the expected axis (None if not given)"}, "equation": "Windows: Ag1 108 to 127, Ag2 236 to 262, Ag3 336 to 354 cm-1 (Mondal 2025: 114, 244, 344 at 300 K; Pawbake 2023: 117, 257, 345 at 300 K and 121, 254, 346 at 5 K). Axis of maximum parallel intensity: Ag1, Ag3 -> b for 1.58 to 2.33 eV; Ag2 -> a for E_L >= 2.12 eV (measured 2.25, 2.33), near isotropic for 2.02 < E_L < 2.12 (switch near 2.07 eV), b for 1.94 to 2.02 eV (measured 1.96), a at 1.58 eV. b_axis_angle = max_parallel_angle if the mode is along b, else + 90 deg.", "validity": {"laser_eV": [1.55, 2.36], "temperature": "300 K in the polarization study (4L to 62 nm flakes)", "geometry": "backscattering along c (k || c); B2g modes at 92, 194, 301 cm-1 appear only with a tilted sample (Pawbake 2023, p. 3)"}, "source": {"citation": "Mondal et al. 2025, npj 2D Mater. (arXiv 2410.22164)", "locator": "p. 2 (Ag1 114, Ag2 244, Ag3 344 cm-1 in 4L at 300 K; axes at 2.33 and 1.96 eV, Figs. 2c,d), p. 3 and Fig. 3 (Ag2 switches from a to b near 2.07 eV; back to a at 1.58 eV), abstract (Ag1 and Ag3 along b at every laser energy)", "doi": null, "arxiv": "2410.22164"}, "caveats": ["Laser energies 2.0 to 2.4 eV and the excitons near 1.65, 1.87 and 1.95 eV (Mondal 2025, p. 4) make relative intensities resonant; compare axes, not intensity ratios, across lasers.", "Ag2 sits at 244 cm-1 in 4L at 300 K (Mondal 2025) and at 254 to 257 cm-1 in bulk (Pawbake 2023); the window covers both."], "self_tests": [{"inputs": {"position_cm1": 114.0, "laser_eV": 2.33}, "expected": {"mode_label": "Ag1", "expected_max_axis": "b"}, "tolerance": {}, "locator": "p. 2: Ag1 (114 cm-1) maximum along b at 2.33 eV, Fig. 2c"}, {"inputs": {"position_cm1": 244.0, "laser_eV": 2.33}, "expected": {"mode_label": "Ag2", "expected_max_axis": "a"}, "tolerance": {}, "locator": "p. 2: Ag2 (244 cm-1) maximum along a at 2.33 eV, Fig. 2c"}, {"inputs": {"position_cm1": 244.0, "laser_eV": 1.96}, "expected": {"mode_label": "Ag2", "expected_max_axis": "b"}, "tolerance": {}, "locator": "pp. 2 to 3: all three modes maximum along b at 1.96 eV, Fig. 2d"}, {"inputs": {"position_cm1": 344.0, "laser_eV": 1.96}, "expected": {"mode_label": "Ag3", "expected_max_axis": "b"}, "tolerance": {}, "locator": "pp. 2 to 3: Ag3 (344 cm-1) maximum along b at 1.96 eV, Fig. 2d"}, {"inputs": {"position_cm1": 244.0, "laser_eV": 1.58}, "expected": {"mode_label": "Ag2", "expected_max_axis": "a"}, "tolerance": {}, "locator": "p. 3: at 1.58 eV the Ag2 polarization switches back to a"}]}]}
